import { Request, Response, NextFunction } from 'express';
import { body, validationResult } from 'express-validator';
import { AppError } from '../utils/appError';

export const validateRequest = (req: Request, _res: Response, next: NextFunction): void => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    throw new AppError('Validation failed', 400);
  }
  next();
};

export const validateAppointment = (req: Request, _res: Response, next: NextFunction): void => {
  const { doctorId, patientId, date, time } = req.body;
  
  if (!doctorId || !patientId || !date || !time) {
    throw new AppError('Missing required fields', 400);
  }
  
  next();
};

export const validatePrescription = (req: Request, _res: Response, next: NextFunction): void => {
  const { patientId, doctorId, medications } = req.body;
  
  if (!patientId || !doctorId || !medications || !Array.isArray(medications)) {
    throw new AppError('Invalid prescription data', 400);
  }
  
  next();
};

export const validateUser = [
  body('email').isEmail().withMessage('Invalid email format'),
  body('password').isLength({ min: 6 }).withMessage('Password must be at least 6 characters long'),
  body('name').isString().trim().notEmpty().withMessage('Name is required'),
  body('userType').isIn(['admin', 'doctor', 'patient', 'pharmacist']).withMessage('Invalid user type'),
  (req: Request, res: Response, next: NextFunction): void => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      throw new AppError('Validation failed', 400);
    }
    next();
  }
]; 